1	---
2	import { existsSync } from 'node:fs'
3	import { join } from 'node:path'
4	
5	import { content } from '../lib/content'
6	import type { Lang } from '../lib/content'
7	import { previewMode, projectDelay } from '../lib/projects'
8	
9	interface Props {
10	  lang: Lang
11	}
12	
13	const { lang } = Astro.props
14	const t = content[lang]
15	
16	const projects = t.projects.map((project, index) => {
17	  const shot = `/previews/${project.host}.png`
18	  return {
19	    ...project,
20	    delay: projectDelay(index),
21	    iframe: previewMode(project.host) === 'iframe',
22	    // Resolved at build time: the screenshots are still pending from the user, and an
23	    // <img> pointing at a file that is not there renders a broken icon in every browser.
24	    // Absent means no <img> at all, so the striped placeholder of the box shows through.
25	    shot: existsSync(join(process.cwd(), 'public', shot)) ? shot : null,
26	  }
27	})
28	---
29	
30	<section id="projects" class="section-y section-divider" aria-labelledby="projects-title">
31	  <div class="container-page">
32	    <div class="head" data-reveal>
33	      <div class="heading">
34	        <p class="font-mono text-label text-dim">04 / {t.secProjects}</p>
35	        <h2 id="projects-title" class="text-h2">{t.projectsTitle}</h2>
36	      </div>
37	      <p class="sub text-dim">{t.projectsSub}</p>
38	    </div>
39	
40	    <ul class="cards">
41	      {
42	        /* The reveal goes on the `<li>`, one level above the hover transform of the
43	        card: two transforms on one element fight (`MOTION_SPEC` §5). */
44	      }
45	      {
46	        projects.map((project) => (
47	          <li data-reveal data-delay={project.delay}>
48	            <a class="card" href={project.url} target="_blank" rel="noopener noreferrer">
49	              <div class="preview">
50	                {/* Decoration, not content: sandboxed, out of the tab order and out of
51	                the accessibility tree, and never loaded before it is scrolled to. */}
52	                {project.iframe && (
53	                  <iframe
54	                    class="frame"
55	                    src={project.url}
56	                    sandbox=""
57	                    loading="lazy"
58	                    aria-hidden="true"
59	                    tabindex="-1"
60	                  />
61	                )}
62	                {project.shot && <img class="frame" src={project.shot} alt="" loading="lazy" />}
63	                <span class="shimmer" aria-hidden="true" />
64	                <span class="kind font-mono text-label-sm">{project.kind}</span>
65	              </div>
66	
67	              <div class="meta">
68	                <span class="names">
69	                  <span class="text-card-title">{project.name}</span>
70	                  <span class="desc text-dim">{project.desc}</span>
71	                </span>
72	                <span class="arrow font-mono" aria-hidden="true">
73	                  ↗
74	                </span>
75	              </div>
76	            </a>
77	          </li>
78	        ))
79	      }
80	    </ul>
81	  </div>
82	</section>
83	
84	<style>
85	  .head {
86	    display: flex;
87	    align-items: flex-end;
88	    justify-content: space-between;
89	    flex-wrap: wrap;
90	    gap: 24px;
91	    margin-bottom: 40px;
92	  }
93	
94	  .heading {
95	    display: flex;
96	    flex-direction: column;
97	    gap: 14px;
98	  }
99	
100	  .sub {
101	    max-width: 380px;
102	    font-size: 16px;
103	  }
104	
105	  .cards {
106	    display: grid;
107	    grid-template-columns: repeat(auto-fit, minmax(min(100%, 300px), 1fr));
108	    gap: 14px;
109	  }
110	
111	  .cards > li {
112	    display: flex;
113	    min-width: 0;
114	  }
115	
116	  .card {
117	    display: flex;
118	    flex: 1;
119	    flex-direction: column;
120	    border-radius: 24px;
121	    overflow: hidden;
122	    background: var(--color-surface);
123	    border: 1px solid var(--color-line);
124	    color: inherit;
125	    text-decoration: none;
126	    transition:
127	      border-color 0.25s,
128	      box-shadow 0.25s;
129	  }
130	
131	  .card:hover {
132	    border-color: color-mix(in srgb, var(--color-accent) 45%, transparent);
133	    box-shadow: 0 20px 60px var(--color-shadow-card);
134	  }
135	
136	  /* The 4px lift of `DESIGN_SPEC` §4 is motion: with `reduce` the card still lights up
137	     on hover, it just stays where it is. */
138	  @media (prefers-reduced-motion: no-preference) {
139	    .card {
140	      transition:
141	        transform 0.25s,
142	        border-color 0.25s,
143	        box-shadow 0.25s;
144	    }
145	
146	    .card:hover {
147	      transform: translateY(-4px);
148	    }
149	  }
150	
151	  /* The striped placeholder: it is the floor of every preview, so a screenshot that has
152	     not arrived yet leaves the box looking deliberate instead of empty. */
153	  .preview {
154	    position: relative;
155	    aspect-ratio: 16 / 11;
156	    overflow: hidden;
157	    border-bottom: 1px solid var(--color-line);
158	    background: repeating-linear-gradient(
159	      135deg,
160	      color-mix(in srgb, var(--color-ink) 4%, transparent) 0 6px,
161	      transparent 6px 14px
162	    );
163	  }
164	
165	  /* The iframe renders at 400% and is scaled to a quarter, so the site inside lays out
166	     as a desktop viewport instead of as a 300px phone. */
167	  .frame {
168	    position: absolute;
169	    inset: 0;
170	    width: 400%;
171	    height: 400%;
172	    border: 0;
173	    transform: scale(0.25);
174	    transform-origin: 0 0;
175	    pointer-events: none;
176	  }
177	
178	  /* The screenshot shares the class, and overrides the two rules that are the iframe's:
179	     it is already the size of the box. */
180	  img.frame {
181	    width: 100%;
182	    height: 100%;
183	    object-fit: cover;
184	    transform: none;
185	  }
186	
187	  .shimmer {
188	    position: absolute;
189	    top: 0;
190	    bottom: 0;
191	    left: -40%;
192	    width: 40%;
193	    pointer-events: none;
194	    background: linear-gradient(
195	      90deg,
196	      transparent,
197	      color-mix(in srgb, var(--color-accent) 12%, transparent),
198	      transparent
199	    );
200	    transform: skewX(-12deg);
201	  }
202	
203	  .kind {
204	    position: absolute;
205	    top: 14px;
206	    left: 14px;
207	    padding: 5px 10px;
208	    border-radius: 999px;
209	    background: var(--color-glass);
210	    color: var(--color-accent);
211	    /* 10-11px, so the accent needs weight 500 to be legal as text (`DESIGN_SPEC` §6). */
212	    font-weight: 500;
213	    border: 1px solid color-mix(in srgb, var(--color-accent) 30%, transparent);
214	  }
215	
216	  .meta {
217	    display: flex;
218	    flex: 1;
219	    align-items: baseline;
220	    justify-content: space-between;
221	    gap: 14px;
222	    padding: 16px 20px 18px;
223	  }
224	
225	  .names {
226	    display: flex;
227	    flex-direction: column;
228	    gap: 3px;
229	    min-width: 0;
230	  }
231	
232	  .desc {
233	    font-size: 14px;
234	  }
235	
236	  .arrow {
237	    flex: none;
238	    font-size: 12px;
239	    font-weight: 500;
240	    color: var(--color-accent);
241	  }
242	
243	  @media (prefers-reduced-motion: no-preference) {
244	    .shimmer {
245	      animation: shimmer 2.8s ease-in-out infinite;
246	    }
247	  }
248	</style>
